#!/usr/bin/env node
/**
 * Embeds the built @attestrack/consent-js IIFE bundle into worker-core so the
 * Worker can serve `GET /consent.js` first-party (P2.1 — the scaffold
 * `<script src="https://{domain}/consent.js">` tag must work).
 *
 * Runs before build/typecheck/test (see package.json scripts). Turbo's
 * `dependsOn: ^build` guarantees consent-js `dist/` exists first.
 */
import { createHash } from 'node:crypto'
import { readFileSync, writeFileSync, existsSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const pkgDir = join(dirname(fileURLToPath(import.meta.url)), '..')
const bundlePath = join(pkgDir, '..', 'consent-js', 'dist', 'consent.js')
const outPath = join(pkgDir, 'src', 'consent-bundle.generated.ts')

if (!existsSync(bundlePath)) {
  console.error(
    `[embed-consent-bundle] missing ${bundlePath} — build @attestrack/consent-js first (turbo ^build should have done this).`
  )
  process.exit(1)
}

const source = readFileSync(bundlePath, 'utf8')
const hash = createHash('sha256').update(source).digest('hex').slice(0, 16)

const banner = `/* eslint-disable */
// Generated by scripts/embed-consent-bundle.mjs — do not edit, do not commit.
// Source: @attestrack/consent-js dist/consent.js (content hash ${hash}).
`
const body = `${banner}export const CONSENT_JS_SOURCE: string = ${JSON.stringify(source)}\nexport const CONSENT_JS_HASH = ${JSON.stringify(hash)}\n`

let previous = null
try {
  previous = readFileSync(outPath, 'utf8')
} catch {
  /* first generation */
}
if (previous !== body) {
  writeFileSync(outPath, body)
  console.log(`[embed-consent-bundle] wrote consent-bundle.generated.ts (hash ${hash}, ${source.length} bytes)`)
}
